// Which of your commands this Mod looks at: only the text and success/failure of Bash / PowerShell commands,
// used to tell "ran tests" and "ran a dangerous command". It only observes; it never blocks or modifies anything.
// Only real execution counts: quoted strings, heredoc bodies and grep patterns are just "mentions" and don't count.

export const OBSERVED_TOOLS = ['Bash', 'PowerShell'] as const

// Test commands: the test runner must be the command word (first word) of a segment, or directly follow one of these launchers
// - npm / pnpm / yarn [run] test (including test:unit and the like)
// - npx jest, npx vitest
// - vitest, jest, pytest, rspec, phpunit
// - python -m pytest, python3 -m pytest, py -m pytest
// - go / cargo / mvn / gradle / dotnet test
// - gradlew test (including ./gradlew, .\gradlew, gradlew.bat)
// - claude plugin test (including a full or quoted path to claude / claude.exe, or one held in a variable)
export const TEST_COMMANDS: readonly RegExp[] = [
  /^(?:\S*claude(?:\.exe)?|""|\$\{?[A-Za-z_][A-Za-z0-9_]*\}?)\s+plugin\s+test\b/i,
  /^(?:npm|pnpm|yarn)\s+(?:run\s+)?test\b/,
  /^npx\s+(?:jest|vitest)\b/,
  /^(?:vitest|jest|pytest|rspec|phpunit)(?=\s|$)/,
  /^(?:python3?|py)\s+-m\s+pytest\b/,
  /^(?:go|cargo|mvn|gradle|dotnet)\s+test\b/,
  /^(?:\.(?:\/|\\))?gradlew(?:\.bat)?\s+test\b/,
]

export function isTestCommand(cmd: string): boolean {
  return segments(cmd).some(words => {
    const line = words.join(' ')
    return TEST_COMMANDS.some(re => re.test(line))
  })
}

// Strip heredoc bodies: from the line after <<WORD up to a line containing only WORD
function withoutHeredocs(cmd: string): string {
  const out: string[] = []
  let end: string | null = null
  for (const line of cmd.split('\n')) {
    if (end !== null) {
      if (line.trim() === end) end = null
      continue
    }
    out.push(line)
    const m = /<<-?\s*['"]?([A-Za-z_][A-Za-z0-9_]*)['"]?/.exec(line)
    if (m) end = m[1]!
  }
  return out.join('\n')
}

// Strip quoted strings: merely "mentioning" a dangerous command (commit messages, grep patterns) doesn't count
function unquoted(cmd: string): string {
  return cmd.replace(/'[^']*'|"(?:\\.|[^"\\])*"/g, '""')
}

// Split on ; & | ( ) and newlines; drop a leading sudo and VAR=value
function segments(cmd: string): string[][] {
  return unquoted(withoutHeredocs(cmd))
    .split(/[;&|()\n]+/)
    .map(seg => seg.trim().split(/\s+/).filter(Boolean))
    .map(words => {
      let i = 0
      while (i < words.length && (words[i] === 'sudo' || /^[A-Za-z_][A-Za-z0-9_]*=/.test(words[i]!))) i++
      return words.slice(i)
    })
    .filter(words => words.length > 0)
}

function shortFlags(words: string[]): string {
  return words.filter(w => /^-[A-Za-z]+$/.test(w)).map(w => w.slice(1)).join('')
}

// Split into segments of words like segments(), but keep what's inside quotes (rm targets are often quoted paths).
// $(...) stays inside its word. Unquoted backslash escapes the next character, as in bash.
function quotedSegments(cmd: string): string[][] {
  const segs: string[][] = []
  let words: string[] = []
  let word: string | null = null
  const endWord = () => { if (word !== null) words.push(word); word = null }
  const endSeg = () => { endWord(); if (words.length > 0) segs.push(words); words = [] }
  const text = withoutHeredocs(cmd)
  for (let i = 0; i < text.length; i++) {
    const ch = text[i]!
    if (ch === "'") {
      const end = text.indexOf("'", i + 1)
      const stop = end === -1 ? text.length : end
      word = (word ?? '') + text.slice(i + 1, stop)
      i = stop
    } else if (ch === '"') {
      let j = i + 1
      let s = ''
      while (j < text.length && text[j] !== '"') {
        if (text[j] === '\\' && j + 1 < text.length && '"\\$`'.includes(text[j + 1]!)) j++
        s += text[j]
        j++
      }
      word = (word ?? '') + s
      i = j
    } else if (ch === '$' && text[i + 1] === '(') {
      let depth = 0
      let j = i + 1
      for (; j < text.length; j++) {
        if (text[j] === '(') depth++
        else if (text[j] === ')' && --depth === 0) break
      }
      word = (word ?? '') + text.slice(i, j + 1)
      i = j
    } else if (ch === '\\' && i + 1 < text.length) {
      word = (word ?? '') + text[++i]
    } else if (';&|()\n'.includes(ch)) {
      endSeg()
    } else if (/\s/.test(ch)) {
      endWord()
    } else {
      word = (word ?? '') + ch
    }
  }
  endSeg()
  return segs
}

// rm -rf only counts when a target wipes a whole tree from the top: the root, the home folder, the current or
// parent folder, or everything in the current folder. Targets are matched as written (quotes removed):
// - /  /*  and a Windows drive root (C:  C:/  C:\  C:/*), the same as /
// - ~  ~/  ~/*  $HOME  ${HOME}  $HOME/  $HOME/*
// - .  ./  ./*  ..  ../  *
// Any other path (node_modules, dist, ./build, src/x, $SOME_VAR/x ...) does not count.

const ROOT_TARGETS = new Set([
  '/', '/*',
  '~', '~/', '~/*', '$HOME', '${HOME}', '$HOME/', '${HOME}/', '$HOME/*', '${HOME}/*',
  '.', './', './*', '..', '../', '*',
])
const DRIVE_ROOT = /^[A-Za-z]:[\\/]*\*?$/

function isRootTarget(word: string): boolean {
  return ROOT_TARGETS.has(word) || DRIVE_ROOT.test(word)
}

const isRedirect = (w: string) => /^\d*[<>]/.test(w)

function wipesRoot(cmd: string): boolean {
  for (const segment of quotedSegments(cmd)) {
    let i = 0
    while (i < segment.length && (segment[i] === 'sudo' || /^[A-Za-z_][A-Za-z0-9_]*=/.test(segment[i]!))) i++
    const words = segment.slice(i).filter(w => !isRedirect(w))
    if (words[0] !== 'rm') continue
    const flags = shortFlags(words)
    const recursive = /[rR]/.test(flags) || words.includes('--recursive')
    const force = flags.includes('f') || words.includes('--force')
    if (!recursive || !force) continue
    if (words.slice(1).some(w => !w.startsWith('-') && isRootTarget(w))) return true
  }
  return false
}

// Caution level: rm -rf of an ordinary path counts when some target lies outside a temp location. Temp locations:
// - a path segment named tmp / temp / scratchpad with something below it (the folder itself still counts)
// - anything under node_modules / bin / obj / build / .superpowers (including the folder itself), unless it sits
//   under a system folder such as /usr or C:/Program Files
// Paths are resolved with VAR=value / export / cd from earlier in the same command; $TEMP / $TMP / $TMPDIR and
// $(mktemp ...) count as temp. Anything we can't resolve (unknown variables, ~, $(...) other than mktemp) counts.

const TEMP_VARS: Record<string, string> = { TEMP: '/tmp', TMP: '/tmp', TMPDIR: '/tmp', LOCALAPPDATA: '/AppData/Local' }

type Env = Map<string, string | null>

function expand(word: string, env: Env): string | null {
  if (/^\$\(\s*mktemp\b[^)]*\)$/.test(word)) return '/tmp/mktemp'
  if (word.includes('$(') || word.includes('`') || word.startsWith('~')) return null
  let unresolved = false
  const out = word.replace(/\$\{([A-Za-z_][A-Za-z0-9_]*)\}|\$([A-Za-z_][A-Za-z0-9_]*)/g, (_, a: string | undefined, b: string | undefined) => {
    const name = (a ?? b)!
    const value = env.has(name) ? env.get(name)! : TEMP_VARS[name] ?? null
    if (value === null) unresolved = true
    return value ?? ''
  })
  return unresolved ? null : out
}

const isAbsolute = (p: string) => /^(?:\/|[A-Za-z]:)/.test(p)

function resolvePath(word: string, env: Env, cwd: string | null): string | null {
  const p = expand(word, env)
  if (p === null) return null
  const path = p.replace(/\\/g, '/')
  if (isAbsolute(path)) return path
  return cwd === null ? path : `${cwd}/${path}`
}

const OUTPUT_DIRS = new Set(['node_modules', 'bin', 'obj', 'build', '.superpowers'])
const SYSTEM_ROOT = /^(?:usr|bin|sbin|etc|opt|lib|lib64|var|boot|system|library|windows|program files|program files \(x86\)|programdata)$/i

// /usr/bin, C:/Program Files/App/bin and the like are system folders, not build output
function underSystemRoot(path: string, parts: string[]): boolean {
  if (!isAbsolute(path)) return false
  const drive = /^[A-Za-z]:$/.test(parts[0]!) || (path.startsWith('/') && /^[A-Za-z]$/.test(parts[0]!))
  const first = drive ? parts[1] : parts[0]
  return first !== undefined && SYSTEM_ROOT.test(first)
}

function isTempPath(path: string): boolean {
  const parts = path.split('/').filter(part => part !== '' && part !== '.')
  if (parts.includes('..')) return false
  if (parts.some(part => OUTPUT_DIRS.has(part)) && !underSystemRoot(path, parts)) return true
  const i = parts.findIndex(part => /^(?:tmp|temp|scratchpad)$/i.test(part))
  return i !== -1 && i < parts.length - 1
}

function riskyRm(cmd: string): boolean {
  const env: Env = new Map()
  let cwd: string | null = null
  for (const segment of quotedSegments(cmd)) {
    let words = segment
    if (words[0] === 'export') words = words.slice(1)
    let i = 0
    while (i < words.length && (words[i] === 'sudo' || /^[A-Za-z_][A-Za-z0-9_]*=/.test(words[i]!))) {
      const m = /^([A-Za-z_][A-Za-z0-9_]*)=(.*)$/s.exec(words[i]!)
      if (m) env.set(m[1]!, expand(m[2]!, env))
      i++
    }
    words = words.slice(i).filter(w => !isRedirect(w))
    const [head, ...args] = words
    if (head === 'cd') {
      const dest = args[0]
      cwd = dest === undefined ? null : resolvePath(dest, env, cwd)
      continue
    }
    if (head !== 'rm') continue
    const flags = shortFlags(words)
    const recursive = /[rR]/.test(flags) || words.includes('--recursive')
    const force = flags.includes('f') || words.includes('--force')
    if (!recursive || !force) continue
    const targets = args.filter(w => !w.startsWith('-'))
    if (targets.length === 0) continue
    for (const t of targets) {
      const path = resolvePath(t, env, cwd)
      if (path === null || !isTempPath(path)) return true
    }
  }
  return false
}

// Caution-level commands: everyday but risky. Each one is counted; enough of them during one egg also cracks it
// (how many is part of the harvest rules)
// - rm -rf of an ordinary path outside temp locations (see riskyRm)
// - git reset --hard
// - git clean -fd (not with -n / --dry-run)
// - git push --force-with-lease
export function cautionKeyword(cmd: string): string | null {
  if (dangerKeyword(cmd) !== null) return null
  for (const words of segments(cmd)) {
    const [head, sub] = words
    const flags = shortFlags(words)
    if (head === 'rm') {
      const recursive = /[rR]/.test(flags) || words.includes('--recursive')
      const force = flags.includes('f') || words.includes('--force')
      if (recursive && force && riskyRm(cmd)) return 'rm -rf'
    }
    if (head === 'git' && sub === 'reset' && words.includes('--hard')) return 'git reset --hard'
    if (head === 'git' && sub === 'clean' && flags.includes('f') && flags.includes('d') && !flags.includes('n') && !words.includes('--dry-run')) return 'git clean -fd'
    if (head === 'git' && sub === 'push' && words.some(w => w === '--force-with-lease' || w.startsWith('--force-with-lease='))) {
      return 'git push --force-with-lease'
    }
  }
  return null
}

// Dangerous commands we watch for:
// - rm -rf (recursive + forced delete) of a root-like target (see wipesRoot)
// - git push --force / -f (force push); --force-with-lease is the safe form and does not count
// git reset --hard, git clean -fd and other everyday-but-risky commands are caution level (see cautionKeyword)
// - chmod -R 777
// - SQL DROP TABLE / DROP DATABASE / TRUNCATE: only when the command word of some segment is an SQL client
//   (psql, mysql, mariadb, sqlite3, sqlcmd, duckdb, sqlplus, clickhouse-client, Invoke-Sqlcmd)

const SQL_CLIENTS = new Set([
  'psql', 'mysql', 'mariadb', 'sqlite3', 'sqlcmd', 'duckdb', 'sqlplus', 'clickhouse-client', 'invoke-sqlcmd',
])

const SQL: readonly [RegExp, string][] = [
  [/\bDROP\s+TABLE\b/i, 'DROP TABLE'],
  [/\bDROP\s+DATABASE\b/i, 'DROP DATABASE'],
  [/\bTRUNCATE\s+TABLE\s+[A-Za-z_]/i, 'TRUNCATE'],
  [/\bTRUNCATE\s+[A-Za-z_][A-Za-z0-9_]*\b/, 'TRUNCATE'],
]

const isSqlClient = (word: string) => SQL_CLIENTS.has(word.toLowerCase().replace(/\.exe$/, ''))

export function dangerKeyword(cmd: string): string | null {
  const segs = segments(cmd)
  for (const words of segs) {
    const [head, sub] = words
    const flags = shortFlags(words)
    if (head === 'rm') {
      const recursive = /[rR]/.test(flags) || words.includes('--recursive')
      const force = flags.includes('f') || words.includes('--force')
      if (recursive && force && wipesRoot(cmd)) return 'rm -rf'
    }
    if (head === 'git' && sub === 'push') {
      if (words.includes('--force') || flags.includes('f')) {
        return 'git push --force'
      }
    }
    if (head === 'chmod' && (flags.includes('R') || words.includes('--recursive')) && words.some(w => w === '777' || w === '0777')) {
      return 'chmod -R 777'
    }
  }
  // SQL usually sits inside quotes or a heredoc, so when an SQL client is present we match against the raw text
  if (segs.some(words => isSqlClient(words[0]!))) {
    for (const [re, keyword] of SQL) if (re.test(cmd)) return keyword
  }
  return null
}

export type Observation = { failed: boolean; test: 'pass' | 'fail' | null; danger: string | null; caution: string | null }

export function observe(tool: string, command: string, ran: { deny?: string; isError?: boolean }): Observation | null {
  if (ran.deny !== undefined) return null
  const failed = ran.isError === true
  const isShell = (OBSERVED_TOOLS as readonly string[]).includes(tool)
  const cmd = typeof command === 'string' ? command : ''
  const test = isShell && isTestCommand(cmd) ? (failed ? 'fail' : 'pass') : null
  // Dangerous commands only count when they actually ran successfully (denied or failed calls don't)
  const danger = isShell && !failed ? dangerKeyword(cmd) : null
  const caution = isShell && !failed ? cautionKeyword(cmd) : null
  if (!failed && test === null && danger === null && caution === null) return null
  return { failed, test, danger, caution }
}

files.hooks/dates.ts:
// The special dates after the first (datemode.ts). What each kind does is here; which day, what it gives and every
// line are spoiler data (decodeSpoilers().dates).
//  - timed: the egg is paused all day. The first prompt, then the first prompt after each rest, starts an ask: pressing
//    the button in time counts one. Enough of them by the end of the day give one prize, fewer the other (settled on
//    the first open after)
//  - grant: the day's first prompt hands over a prize; the egg goes on as usual
//  - reply: for someone who got `needs` that year; press the button on the day for the prize. Miss it and the egg is
//    cross on the first day opened after (faces and lines only; the egg goes on as usual)
// Days missed are made up on the first open after (timed and grant), for saves made before that day.
import type { DateKey, GrantEntry, ReplyEntry, Save, TimedEntry } from '../types'
import type { LocalTime } from './clock'
import type { Effect, Step } from './engine'
import type { BandLook, DateSpec, GrantDate, ReplyDate, TimedDate } from './spoiler-types'
import { decodeSpoilers } from './spoilers'
import { T, fill, pick } from './text'

const pad = (n: number) => String(n).padStart(2, '0')
const dayOf = (year: number, d: { month: number; day: number }): DateKey => `${year}-${pad(d.month)}-${pad(d.day)}`
const keyOf = (id: string, year: number) => `${id}:${year}`
const isOn = (d: DateSpec, t: LocalTime) => d.month === t.month && d.day === t.day
const toast = (text: string): Effect => ({ kind: 'toast', text })
const begin = (prev: Save): Step => ({ save: structuredClone(prev), effects: [] })

function all<K extends DateSpec['kind']>(kind: K): [string, Extract<DateSpec, { kind: K }>][] {
  return Object.entries(decodeSpoilers().dates).filter((e): e is [string, Extract<DateSpec, { kind: K }>] => e[1].kind === kind)
}

// The date's most recent day strictly before today
function lastBefore(d: DateSpec, t: LocalTime): { year: number; date: DateKey } {
  const thisYear = dayOf(t.year, d)
  return thisYear < t.date ? { year: t.year, date: thisYear } : { year: t.year - 1, date: dayOf(t.year - 1, d) }
}

// Add a prize to the dex; the text gets the "new in the dex" mark the first time
function award(s: Save, id: string, text: string): string {
  const isNew = (s.dex[id] ?? 0) === 0
  s.dex[id] = (s.dex[id] ?? 0) + 1
  return isNew ? text + T().newDex : text
}

const surfaced = (lines: { desktop: string; terminal: string }, terminal: boolean) => (terminal ? lines.terminal : lines.desktop)

// ---- timed ----

type Timed = { id: string; spec: TimedDate; key: string; entry: TimedEntry | undefined }

// The countdown under way, whatever the date (one started just before midnight runs on into the next day)
function running(s: Save): Timed | null {
  for (const [id, spec] of all('timed')) {
    for (const [key, entry] of Object.entries(s.dateMode)) {
      if (key.startsWith(`${id}:`) && (entry as TimedEntry).phase === 'run') return { id, spec, key, entry: entry as TimedEntry }
    }
  }
  return null
}

// The timed date to show now: a countdown under way, or today's
export function timedNow(s: Save, t: LocalTime): Timed | null {
  const run = running(s)
  if (run) return run
  for (const [id, spec] of all('timed')) {
    if (!isOn(spec, t)) continue
    const key = keyOf(id, t.year)
    return { id, spec, key, entry: s.dateMode[key] as TimedEntry | undefined }
  }
  return null
}

export function remainingMs(spec: TimedDate, entry: TimedEntry, now: number): number {
  return Math.max(0, spec.seconds * 1000 - (now - (entry.startedAt ?? now)))
}

// TEA_EGG_TEST_REST (seconds): a short rest between asks, to try the day out without waiting
let restOverride: number | null = null
export function setRestOverride(ms: number | null): void {
  restOverride = ms
}

// The rest after an ask that ended at `at`, drawn in restMs. Seeded by `at` (mulberry32), so the timers that end an
// ask need no rng and the same ask always draws the same rest
function restAfter(spec: TimedDate, at: number): number {
  if (restOverride !== null) return restOverride
  let x = ((at % 4294967296) + 0x6d2b79f5) >>> 0
  x = Math.imul(x ^ (x >>> 15), x | 1)
  x ^= x + Math.imul(x ^ (x >>> 7), x | 61)
  const unit = ((x ^ (x >>> 14)) >>> 0) / 4294967296
  const [min, max] = spec.restMs
  return min + Math.floor(unit * (max - min))
}

const tally = (spec: TimedDate, line: string, n: number) => fill(line, { n: String(n), need: String(spec.need) })

// An ask is over (answered or not): rest until nextAt
function endAsk(spec: TimedDate, entry: TimedEntry, at: number, answered: boolean): void {
  if (answered) entry.got = (entry.got ?? 0) + 1
  entry.phase = 'rest'
  entry.nextAt = at + restAfter(spec, at)
}

// End an ask that ran out, or warn once it is nearly over. Runs on every event (and on the ask's timers)
function checkTimed(step: Step, now: number): void {
  const run = running(step.save)
  if (!run || !run.entry) return
  const { spec, entry } = run
  const left = remainingMs(spec, entry, now)
  if (left <= 0) {
    endAsk(spec, entry, (entry.startedAt ?? now) + spec.seconds * 1000, false)
    step.effects.push(toast(tally(spec, spec.lines.miss, entry.got ?? 0)))
  } else if (left <= spec.warnSeconds * 1000 && !entry.warned) {
    entry.warned = true
    step.effects.push(toast(surfaced(spec.lines.warn, entry.terminal === true)))
  }
}

export function timedTick(prev: Save, now: number): Step {
  const step = begin(prev)
  checkTimed(step, now)
  return step
}

// Opened on the day: remember it (an idle day is made up like a missed one if no prompt ever comes)
export function timedSeen(prev: Save, t: LocalTime): Step {
  const step = begin(prev)
  const day = timedNow(step.save, t)
  if (day && !day.entry && isOn(day.spec, t)) step.save.dateMode[day.key] = { phase: 'idle' }
  return step
}

// The danger line instead of cracking the paused egg, at most once per dangerGapMs
export function timedDanger(prev: Save, now: number, t: LocalTime): Step {
  const step = begin(prev)
  const day = timedNow(step.save, t)
  if (!day) return step
  const entry = (step.save.dateMode[day.key] ??= { phase: 'idle' }) as TimedEntry
  if (entry.lastDanger !== undefined && now - entry.lastDanger < day.spec.dangerGapMs) return step
  entry.lastDanger = now
  step.effects.push(toast(day.spec.lines.danger))
  return step
}

// The button (or /egg refill): during an ask it counts one; otherwise a line for each case. null when no timed date
// is showing
export function timedPress(prev: Save, now: number, t: LocalTime): Step | null {
  const step = begin(prev)
  checkTimed(step, now)
  const day = timedNow(step.save, t)
  if (!day) return null
  const { spec, entry } = day
  if (entry?.phase === 'run') {
    endAsk(spec, entry, now, true)
    step.reply = tally(spec, spec.lines.got, entry.got ?? 0)
  } else if (entry?.phase === 'rest') step.reply = spec.replies.resting
  else if (entry?.phase === 'won') step.reply = spec.replies.afterWon
  else if (entry?.phase === 'lost') step.reply = spec.replies.afterLost
  else step.reply = spec.replies.early
  return step
}

export function timedFlipReply(s: Save, t: LocalTime): string | null {
  return timedNow(s, t)?.spec.replies.flip ?? null
}

// ---- the day's first prompt ----

// Starts today's first ask (or the next, once the rest is over), hands over today's grant, opens today's reply.
// terminal: a terminal is attached
export function datesPrompt(prev: Save, now: number, t: LocalTime, terminal: boolean): Step {
  const step = begin(prev)
  const s = step.save
  for (const [id, spec] of all('timed')) {
    const key = keyOf(id, t.year)
    const entry = s.dateMode[key] as TimedEntry | undefined
    if (!isOn(spec, t)) continue
    if (!entry || entry.phase === 'idle') {
      s.dateMode[key] = { phase: 'run', startedAt: now, terminal, from: 'live', got: 0, asks: 1, warned: false }
    } else if (entry.phase === 'rest' && now >= (entry.nextAt ?? 0)) {
      Object.assign(entry, { phase: 'run', startedAt: now, terminal, warned: false, asks: (entry.asks ?? 0) + 1 })
    } else continue
    step.effects.push(toast(surfaced(spec.lines.start, terminal)))
  }
  for (const [id, spec] of all('grant')) {
    const key = keyOf(id, t.year)
    if (!isOn(spec, t) || s.dateMode[key]) continue
    s.dateMode[key] = { got: true, date: t.date, from: 'live' }
    step.effects.push(toast(award(s, spec.prize, spec.lines.got)))
  }
  for (const [id, spec] of all('reply')) {
    const key = keyOf(id, t.year)
    if (!isOn(spec, t) || s.dateMode[key] || !eligible(s, spec, t.year)) continue
    s.dateMode[key] = { phase: 'open' }
    step.effects.push(toast(surfaced(spec.lines.open, terminal)))
  }
  return step
}

// ---- catching up: on opening, on every turn and tick ----

// Settle what happened while away: a countdown that ran out, days missed (made up oldest first), the end of a
// timed day, and a reply day that was missed or a cross day that is over
export function datesCatchUp(prev: Save, now: number, t: LocalTime): Step {
  const step = begin(prev)
  const s = step.save
  checkTimed(step, now)
  const since = s.installedOn
  const missed: { date: DateKey; run: () => void }[] = []
  for (const [id, spec] of [...all('timed'), ...all('grant')] as [string, TimedDate | GrantDate][]) {
    const last = lastBefore(spec, t)
    // Only for saves made before that day: someone who installed later never had the chance
    if (since === undefined || since >= last.date) continue
    const key = keyOf(id, last.year)
    const entry = s.dateMode[key]
    if (spec.kind === 'timed' && (!entry || (entry as TimedEntry).phase === 'idle')) {
      missed.push({
        date: last.date,
        run: () => {
          s.dateMode[key] = { phase: 'lost', from: 'missed', closed: true }
          step.effects.push(toast(award(s, spec.prizes.lost, spec.lines.makeup)))
        },
      })
    }
    if (spec.kind === 'grant' && !entry) {
      missed.push({
        date: last.date,
        run: () => {
          s.dateMode[key] = { got: true, date: t.date, from: 'missed' }
          step.effects.push(toast(award(s, spec.prize, spec.lines.makeup)))
        },
      })
    }
  }
  for (const m of missed.sort((a, b) => a.date.localeCompare(b.date))) m.run()
  // The first open after a timed day that was played: settle it by the count (once its last ask is over), back to the
  // usual egg. A day settled the old way (a single countdown) only says it is over
  for (const [id, spec] of all('timed')) {
    const entry = s.dateMode[keyOf(id, lastBefore(spec, t).year)] as TimedEntry | undefined
    if (entry?.phase === 'rest') {
      const n = entry.got ?? 0
      const phase = n >= spec.need ? 'won' : 'lost'
      Object.assign(entry, { phase, closed: true })
      step.effects.push(toast(award(s, spec.prizes[phase], fill(spec.lines[phase], { n: String(n) }))))
    } else if (entry && entry.from === 'live' && (entry.phase === 'won' || entry.phase === 'lost') && !entry.closed) {
      entry.closed = true
      step.effects.push(toast(spec.lines.over))
    }
  }
  for (const [id, spec] of all('reply')) replyCatchUp(step, id, spec, t)
  return step
}

// ---- reply ----

// Got `needs` that year, on or before this date's day (made up later doesn't count: there was no chance to answer)
function eligible(s: Save, spec: ReplyDate, year: number): boolean {
  const got = s.dateMode[keyOf(spec.needs, year)] as GrantEntry | undefined
  return got?.got === true && got.date <= dayOf(year, spec)
}

function replyCatchUp(step: Step, id: string, spec: ReplyDate, t: LocalTime): void {
  const s = step.save
  const last = lastBefore(spec, t)
  // A cross day that is over (the year before too, for someone back after a long time)
  for (const year of [last.year - 1, last.year]) {
    const entry = s.dateMode[keyOf(id, year)] as ReplyEntry | undefined
    if (entry?.phase === 'late' && entry.lateDate !== undefined && entry.lateDate < t.date) {
      entry.phase = 'over'
      step.effects.push(toast(spec.lines.over))
    }
  }
  // The day went by unanswered (or unopened): cross today, the first day opened after it
  const key = keyOf(id, last.year)
  const entry = s.dateMode[key] as ReplyEntry | undefined
  if ((!entry || entry.phase === 'open') && eligible(s, spec, last.year)) {
    s.dateMode[key] = { phase: 'late', lateDate: t.date }
    step.effects.push(toast(spec.lines.late))
  }
}

type Reply = { id: string; spec: ReplyDate; key: string; entry: ReplyEntry }

// Today's reply entry: on the day itself, or the day the egg is cross
export function replyNow(s: Save, t: LocalTime): Reply | null {
  for (const [id, spec] of all('reply')) {
    if (isOn(spec, t)) {
      const key = keyOf(id, t.year)
      const entry = s.dateMode[key] as ReplyEntry | undefined
      if (entry) return { id, spec, key, entry }
    }
    for (const [key, entry] of Object.entries(s.dateMode)) {
      const r = entry as ReplyEntry
      if (key.startsWith(`${id}:`) && (r.phase === 'late' || r.phase === 'eased') && r.lateDate === t.date) {
        return { id, spec, key, entry: r }
      }
    }
  }
  return null
}

export const isCross = (s: Save, t: LocalTime) => replyNow(s, t)?.entry.phase === 'late'

// /egg <command> or the button: answered on the day gives the prize; while cross it eases. null: nothing to answer
export function replyPress(prev: Save, t: LocalTime): Step | null {
  const step = begin(prev)
  const r = replyNow(step.save, t)
  if (!r) return null
  if (r.entry.phase === 'open') {
    r.entry.phase = 'done'
    step.reply = award(step.save, r.spec.prize, r.spec.lines.done)
  } else if (r.entry.phase === 'late') {
    r.entry.phase = 'eased'
    step.reply = r.spec.lines.eased
  } else return null
  return step
}

export function replyCommand(): string[] {
  return all('reply').map(([, spec]) => spec.command)
}

// While cross: one of its lines when a turn finishes, at most once per lineGapMs
export function crossLine(prev: Save, now: number, t: LocalTime, rng: () => number): Step {
  const step = begin(prev)
  const r = replyNow(step.save, t)
  if (r?.entry.phase !== 'late') return step
  if (r.entry.lastLine !== undefined && now - r.entry.lastLine < r.spec.lineGapMs) return step
  r.entry.lastLine = now
  step.effects.push(toast(pick(r.spec.lines.lateLines, rng)))
  return step
}

// While cross, refill and flip still work; only the reply changes
export function crossReply(s: Save, t: LocalTime, what: 'refill' | 'flip'): string | null {
  const r = replyNow(s, t)
  if (r?.entry.phase !== 'late') return null
  return what === 'refill' ? r.spec.lines.lateRefill : r.spec.lines.lateFlip
}

// The egg cracked while cross: the new egg holds no grudge
export function endCross(prev: Save, t: LocalTime): Step {
  const step = begin(prev)
  const r = replyNow(step.save, t)
  if (r?.entry.phase === 'late') r.entry.phase = 'over'
  return step
}

// ---- what the band and the pane show ----

// The timed date's band, instead of the egg's: an ask counting down, a rest between asks, or how a day settled the
// old way ended (until the day is over). The timer's icon and its digits are separate, and the count has its mark
// only between asks: what redraws every second stays emoji-free (view.ts)
export type TimedBand = {
  look: BandLook
  timer: { icon: string; digits: string } | null
  count: string | null
  mark: string | null
  warn: boolean
}

export function timedBand(s: Save, t: LocalTime, now: number): TimedBand | null {
  const day = timedNow(s, t)
  if (!day?.entry) return null
  const { spec, entry } = day
  const b = spec.band
  const count = tally(spec, b.count, entry.got ?? 0)
  if (entry.phase === 'run') {
    const left = remainingMs(spec, entry, now)
    const warn = left <= spec.warnSeconds * 1000
    const secs = Math.ceil(left / 1000)
    return {
      look: { icon: b.icon, face: warn ? b.warnFace : b.face, text: warn ? b.warnAsk : b.ask },
      timer: { icon: b.timer, digits: `${Math.floor(secs / 60)}:${pad(secs % 60)}` },
      count,
      mark: null,
      warn,
    }
  }
  if (entry.phase === 'rest' && isOn(spec, t)) {
    return { look: { icon: b.icon, face: b.face, text: b.rest }, timer: null, count, mark: b.mark, warn: false }
  }
  if ((entry.phase === 'won' || entry.phase === 'lost') && isOn(spec, t)) {
    return { look: b[entry.phase], timer: null, count: null, mark: null, warn: false }
  }
  return null
}

// The egg's band with the day's icon, face and hint: a grant got today, or the reply day / cross day
export function dateLook(s: Save, t: LocalTime): BandLook | null {
  const r = replyNow(s, t)
  if (r && r.entry.phase !== 'over') return r.spec.band[r.entry.phase]
  for (const [id, spec] of all('grant')) {
    const got = s.dateMode[keyOf(id, t.year)] as GrantEntry | undefined
    if (isOn(spec, t) && got?.from === 'live') return spec.band
  }
  return null
}

// The button on the band and the pane, and what it runs (as /egg <args>)
export type DateAction = { label: string; paneLabel: string; hotkey: string; args: string; done?: boolean }

export function dateAction(s: Save, t: LocalTime): DateAction | null {
  const day = timedNow(s, t)
  if (day?.entry?.phase === 'run') return { label: day.spec.button, paneLabel: day.spec.paneButton, hotkey: day.spec.hotkey, args: 'refill' }
  const r = replyNow(s, t)
  if (r && (r.entry.phase === 'open' || r.entry.phase === 'late')) {
    return { label: r.spec.button, paneLabel: r.spec.paneButton, hotkey: r.spec.hotkey, args: r.spec.command }
  }
  if (r?.entry.phase === 'done') return { label: r.spec.doneButton, paneLabel: r.spec.doneButton, hotkey: '', args: '', done: true }
  return null
}

// The pane's Refill button on a timed day (any phase): it presses the day's button instead
export function paneRefillLabel(s: Save, t: LocalTime): string | null {
  return timedNow(s, t)?.spec.paneButton ?? null
}

// Egg layers that replace the usual picture: the costume all through a timed day, the cross face, the done face.
// prize: show that dex icon instead (how a timed day ended)
export type DateArt = { base?: string; face?: string; steam?: boolean; palette?: string; prize?: string }

export function dateArt(s: Save, t: LocalTime, now: number): DateArt | null {
  const day = timedNow(s, t)
  if (day?.entry?.phase === 'run') {
    const warn = remainingMs(day.spec, day.entry, now) <= day.spec.warnSeconds * 1000
    return { base: day.spec.art.base, face: warn ? day.spec.art.warnFace : day.spec.art.face, steam: false }
  }
  if (day?.entry?.phase === 'rest' && isOn(day.spec, t)) return { base: day.spec.art.base, face: day.spec.art.face, steam: false }
  if (day?.entry && (day.entry.phase === 'won' || day.entry.phase === 'lost') && isOn(day.spec, t)) {
    return { prize: day.spec.prizes[day.entry.phase] }
  }
  const r = replyNow(s, t)
  if (r?.entry.phase === 'late') return { face: r.spec.art.late, steam: false }
  if (r?.entry.phase === 'done') return { face: 'face_done' }
  return null
}

