import type { Save } from '../types'
import type { LocalTime } from './clock'
import { dateLook, timedBand } from './dates'
import { isSpecialDay, specialBand } from './datemode'
import { RULES } from './engine'
import { predictHint } from './rules'
import { T } from './text'

export type Face = 'happy' | 'normal' | 'bored' | 'dry' | 'sleep' | 'flip' | 'done'

export const FACE_TEXT: Record<Face, string> = {
  happy: '(•ᴗ•)',
  normal: '(•_•)',
  bored: '(-_-)',
  dry: '(；へ；)',
  sleep: '(－ω－) zzZ',
  flip: '(•̀ᴗ•́)↻',
  done: '(✧ᴗ✧)',
}

const DONE_MS = 10 * 60_000

export function faceOf(s: Save, t: LocalTime, now: number): Face {
  if (s.harvestedAt !== null && now - s.harvestedAt < DONE_MS) return 'done'
  if (t.hour < RULES.nightEndHour) return 'sleep'
  if (s.egg.broth <= 0) return 'dry'
  if (s.egg.flipWantedAt !== null) return 'flip'
  if (s.egg.mood >= 70) return 'happy'
  if (s.egg.mood < 30) return 'bored'
  return 'normal'
}

export function stageOf(progress: number): 0 | 1 | 2 | 3 {
  if (progress < 20) return 0
  if (progress < 40) return 1
  if (progress < 70) return 2
  return 3
}

// Face color by stage. The band is drawn on light and dark themes alike and render can't tell which,
// so raw eggs keep the default text color (no color) and the brown stages are mid-tones readable on both
export const STAGE_COLOR = [undefined, undefined, '#c98f5c', '#9a6230'] as const

function charWidth(cp: number): number {
  if ((cp >= 0x0300 && cp <= 0x036f) || cp === 0xfe0f || cp === 0x200d) return 0
  if (
    (cp >= 0x1100 && cp <= 0x115f) || (cp >= 0x2e80 && cp <= 0xa4cf) || (cp >= 0xac00 && cp <= 0xd7a3) ||
    (cp >= 0xf900 && cp <= 0xfaff) || (cp >= 0xfe30 && cp <= 0xfe4f) || (cp >= 0xff00 && cp <= 0xff60) ||
    (cp >= 0xffe0 && cp <= 0xffe6) || (cp >= 0x1f300 && cp <= 0x1faff) || (cp >= 0x20000 && cp <= 0x3fffd)
  ) return 2
  return 1
}

export function strWidth(text: string): number {
  let w = 0
  for (const ch of text) w += charWidth(ch.codePointAt(0)!)
  return w
}

export function truncate(text: string, columns: number): string {
  if (strWidth(text) <= columns) return text
  let out = ''
  for (const ch of text) {
    if (strWidth(out + ch) > columns - 1) break
    out += ch
  }
  return out + '…'
}

export function bar(value: number, cells: number): string {
  const filled = Math.round((Math.max(0, Math.min(100, value)) / 100) * cells)
  return '█'.repeat(filled) + '░'.repeat(cells - filled)
}

export function hintOf(s: Save, now: number): string | null {
  if (s.egg.broth <= 0) return T().brothEmptyHint
  if (s.egg.broth < RULES.lowBroth) return T().brothLow
  if (s.egg.flipWantedAt !== null) return T().flipHint
  return predictHint(s.egg, now)
}

// keep: the higher, the longer it stays when the band is too narrow (ties: the rightmost goes first)
export type Seg = { text: string; color?: string; dim?: boolean; sep?: boolean; keep?: number }

const sep = (): Seg => ({ text: T().separator, dim: true, sep: true })

export function bandSegments(s: Save, t: LocalTime, now: number): Seg[] {
  if (isSpecialDay(t)) {
    // The human in the pot: its number and progress, then its broth (the hint goes first when narrow)
    const b = specialBand(s, t)
    return [
      { text: ` ${b.icon}${b.face}  ${b.who} ${bar(b.human, 10)} ${Math.round(b.human)}%` },
      sep(),
      { text: `${T().broth} ${bar(b.broth, 5)}`, keep: 1 },
      sep(),
      { text: b.hint, dim: true },
    ]
  }
  // A timed special date: its own band while counting down and once settled (dates.ts); the name goes before the timer
  const timed = timedBand(s, t, now)
  if (timed) {
    // No emoji left of the digits: the band redraws every second, and a terminal that draws emoji one column wide (the
    // desktop app's terminal pane) put every changing cell right of an emoji a column off, leaving stray characters.
    // The timer's emoji sits right after the digits (always m:ss, so it never moves). The count only gets its mark
    // between asks, when nothing redraws every second
    const segs: Seg[] = [{ text: ` ${timed.look.face}` }, { text: `  ${s.egg.name} #${s.egg.no}`, keep: 1 }]
    if (timed.timer !== null) segs.push(sep(), { text: timed.timer.digits, keep: 3 }, { text: ` ${timed.timer.icon}`, keep: 3 })
    if (timed.count !== null) segs.push(sep(), { text: timed.count + (timed.mark !== null ? ` ${timed.mark}` : ''), keep: 2 })
    segs.push(sep(), { text: timed.look.text, dim: true })
    return segs
  }
  // Another special date today: its icon, face and line in place of the egg's
  const look = dateLook(s, t)
  const stage = stageOf(s.egg.progress)
  const segs: Seg[] = [
    { text: look ? ` ${look.icon}` : ` 🥚${stage === 1 ? '⸝' : ''}` },
    { text: look ? look.face : FACE_TEXT[faceOf(s, t, now)], color: STAGE_COLOR[stage] },
    { text: `  ${s.egg.name} #${s.egg.no}` },
    sep(),
    { text: `${T().flavor} ${bar(s.egg.progress, 10)} ${Math.floor(s.egg.progress)}%` },
    sep(),
    { text: `${T().broth} ${bar(s.egg.broth, 5)}` },
  ]
  const hint = look ? look.text : hintOf(s, now)
  if (hint !== null) segs.push(sep(), { text: hint, dim: true })
  return segs
}

// Drop whole segments until it fits: the lowest keep first, from the right on a tie, with the separator before it
// (a separator left at the end goes too).
// The first segment (the egg) always stays, truncated if needed
export function fitSegments(segs: Seg[], columns: number): Seg[] {
  const out = [...segs]
  const width = () => out.reduce((w, seg) => w + strWidth(seg.text), 0)
  while (out.length > 1 && width() > columns) {
    let drop = -1
    for (let i = out.length - 1; i >= 1; i--) {
      if (out[i]!.sep !== true && (drop < 0 || (out[i]!.keep ?? 0) < (out[drop]!.keep ?? 0))) drop = i
    }
    if (drop < 0) break
    out.splice(drop, 1)
    if (out[drop - 1]?.sep === true) out.splice(drop - 1, 1)
  }
  while (out.length > 1 && out[out.length - 1]!.sep === true) out.pop()
  if (width() > columns) out[0] = { ...out[0]!, text: truncate(out[0]!.text, columns) }
  return out
}

